   237|async function runSupabaseResetOwnerPassword(input: Record<string, unknown>): Promise<Record<string, unknown>> {
   238|  const email = readTrimmed(input.email).toLowerCase();
   239|  const newPassword = readTrimmed(input.newPassword) || readTrimmed(input.password);
   240|  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
   241|    throw new Error('A valid owner email is required for supabase_reset_owner_password.');
   242|  }
   243|  if (!newPassword || newPassword.length < 12) {
   244|    throw new Error('A new password of at least 12 characters is required for supabase_reset_owner_password (enterprise policy).');
   245|  }
   246|  const admin = resolveSupabaseAdminClient();
   247|  const { data: listData, error: listError } = await admin.auth.admin.listUsers({ page: 1, perPage: 1000 });
   248|  if (listError) {
   249|    throw new Error(`Supabase listUsers failed: ${listError.message}`);
   250|  }
   251|  const user = (listData.users ?? []).find((u) => (u.email ?? '').toLowerCase() === email);
   252|  if (!user) {
   253|    throw new Error(`No Supabase auth user found for email ${email}.`);
   254|  }
   255|  const { data: updateData, error: updateError } = await admin.auth.admin.updateUserById(user.id, {
   256|    password: newPassword,
   257|    email_confirm: true,
   258|    ban_duration: 'none',
   259|  });
   260|  if (updateError || !updateData.user) {
   261|    throw new Error(`Supabase updateUserById failed: ${updateError?.message ?? 'no user returned'}`);
