   264|  try {
   265|    await admin.auth.admin.signOut(user.id, 'global');
   266|  } catch (signOutError) {
   267|    console.log('[SupabaseResetOwnerPassword] Session revocation note:', signOutError instanceof Error ? signOutError.message : 'unknown');
   268|  }
   269|  return {
   270|    provider: 'supabase',
   271|    action: 'supabase_reset_owner_password',
   272|    email,
   273|    userId: user.id,
   274|    passwordReset: true,
   275|    sessionsRevoked: true,
   276|    emailConfirmed: Boolean(updateData.user.email_confirmed_at || updateData.user.confirmed_at) || true,
   277|    timestamp: nowIso(),
