   343|async function ensureSupabaseAuthRedirectUrl(supabaseUrl: string, redirectTo: string): Promise<{
   344|  ok: boolean;
   345|  tokenPresent: boolean;
   346|  projectRef: string | null;
   347|  getStatus?: number;
