   363|  }
   364|  const projectRefMatch = supabaseUrl.match(/https:\/\/([a-z0-9-]+)\.supabase\.co/);
   365|  const projectRef = projectRefMatch?.[1] ?? null;
   366|  if (!projectRef) {
   367|    return { ok: false, tokenPresent: true, projectRef, message: `Could not extract project ref from Supabase URL: ${supabaseUrl}` };
   368|  }
