   373|    const getText = await getResp.text();
   374|    if (!getResp.ok) {
   375|      return { ok: false, tokenPresent: true, projectRef, getStatus: getResp.status, getError: getText.slice(0, 300), message: `GET auth config failed: HTTP ${getResp.status}` };
   376|    }
   377|    const getConfig = JSON.parse(getText) as { uri_allow_list?: string; site_url?: string; };
   378|    const rawAllowList = typeof getConfig.uri_allow_list === 'string' ? getConfig.uri_allow_list : '';
   379|    const redirectUrls = rawAllowList.split(/[\s,]+/).map((u) => u.trim()).filter(Boolean);
   380|    const beforeUrls = [...redirectUrls];
   381|
   382|    if (redirectUrls.includes(redirectTo)) {
   383|      return { ok: true, tokenPresent: true, projectRef, getResponse: getText.slice(0, 400), beforeUrls, afterUrls: beforeUrls, message: 'Redirect URL already allowed.' };
   384|    }
