   387|    // multiple URLs are present, dropping the separator and concatenating values. To guarantee a
   388|    // valid allow-list for the new redirect URL, we REPLACE the list with exactly that URL.
   389|    const nextUrls = [redirectTo];
   390|    const nextAllowList = redirectTo;
