   393|    const patchBody = JSON.stringify({ uri_allow_list: nextAllowList, site_url: 'https://ivxholding.com' });
   394|    const patchResp = await fetch(authUrl, {
   395|      method: 'PATCH',
   396|      headers: { Authorization: `Bearer ${managementToken}`, 'Content-Type': 'application/json', Accept: 'application/json' },
   397|      body: patchBody,
   398|    });
   399|    const patchText = await patchResp.text();
