   405|    // Re-read to verify
   406|    const getResp2 = await fetch(authUrl, { headers: { Authorization: `Bearer ${managementToken}`, Accept: 'application/json' } });
   407|    const getText2 = await getResp2.text();
   408|    const afterConfig = JSON.parse(getText2) as { uri_allow_list?: string; };
   409|    const afterUrls = typeof afterConfig.uri_allow_list === 'string'
   410|      ? afterConfig.uri_allow_list.split(/[\s,]+/).map((u) => u.trim()).filter(Boolean)
